            return [row[:] for row in grid]

        period = h
        for p in range(1, h + 1):
            seen = {}
            for r, color in known.items():
                k = r % p
                if k in seen and seen[k] != color:
                    break
                seen[k] = color
            else:
                period = p
                break

        phase = [None] * period
        for r, color in known.items():
            phase[r % period] = color

        # Fill unconstrained phases by extending the observed cyclic sequence.
        observed = [i for i, color in enumerate(phase) if color is not None]
        for i in range(period):
            if phase[i] is None:
                j = min(observed, key=lambda x: min((i-x) % period, (x-i) % period))
                phase[i] = phase[j]

        return [[phase[r % period]] * w for r in range(h)]

    # Diagonal pattern: the colors repeat symmetrically with distance
    # from the main diagonal, reflecting the known bands at the edge.
    n = min(h, w)
    bands = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                d = abs(c - r)
                bands[d] = grid[r][c]

    for d in range(n):
        if d not in bands:
            mirror = n - 1 - d
            if mirror in bands:
                bands[d] = bands[mirror]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            d = abs(c - r)
            if d in bands:
                out[r][c] = bands[d]
